+      // The locked exe cannot relaunch the session here; the swap already
+      // printed the restart hint.
+      return ApplyUpdateOutcome.unsupportedPlatform;
+    }
+    final restarted = await _restartAfterUpdate(
+      install,
+      launchArgs,
+      spawn: spawn,
+      settleDelay: settleDelay,
+      logLine: log,
+    );
