    io: _TerminalCliIO(headless: parsed.isHeadless),
    env: LocalExecutionEnv(cwd: parsed.cwd ?? Directory.current.path),
    projectDir: parsed.cwd ?? Directory.current.path,
    userDir: _homeDir(),
    strict: _envTruthy('FA_EXT_BOOTSTRAP_STRICT'),
