+    final entry = rawEntry.trim();
+    if (entry.isEmpty) continue;
+    final candidate = File('$entry/fa${Platform.isWindows ? '.exe' : ''}');
+    if (candidate.existsSync()) return candidate.path;
+  }
+  return null;
