  if (answer == null) return;
  final value = answer.trim();
  if (value.isEmpty) return;
  final entries = value == '-'
      ? const <String>[]
      : [
          for (final entry in value.split(','))
            if (entry.trim().isNotEmpty) entry.trim(),
        ];
  await _writeRedactionKey(segments, jsonEncode(entries));
}

