+    final dir = Directory('$root/.fah/logs')..createSync(recursive: true);
+    File('${dir.path}/fa.log').writeAsStringSync(
+      '${DateTime.now().toIso8601String()} $message\n',
+      mode: FileMode.append,
+    );
+  } catch (_) {
+    // Diagnostics must never break the CLI.
+  }
+}
