        runProcess: extractingRunProcess,
        spawn: (_, _) async => false,
        pem: _testPem,
        logLine: log.add,
      );
      expect(outcome, ApplyUpdateOutcome.restartFailed);
      expect(target.readAsStringSync(), 'new-binary');
      expect(log, contains('fa update restart failed'));
    },
