      final repo = _repo;
      if (repo is JsonlSessionRepo) {
        try {
          name = await repo.sessionNameQuick(metadata);
        } on Object {
          name = null; // unreadable file: degrade to the id
        }
      }
    }
    return name ?? metadata.id;
  }

