      // A bare `yes` is a yaml STRING (the yaml package has no 1.1 bools),
      // a quoted 'true' stays a string, numbers and maps are junk too.
      expect(
        () => autoUpdateModeFromYaml('yes'),
        throwsA(
          isA<ConfigException>().having(
            (e) => e.message,
            'message',
            autoUpdateError('yes'),
          ),
