/// Magic bytes of native executables: Mach-O (32/64-bit + fat), ELF, PE.
const _nativeMagics = [
  [0xFE, 0xED, 0xFA, 0xCE], // Mach-O 32-bit
  [0xFE, 0xED, 0xFA, 0xCF], // Mach-O 64-bit
