// `fa session list [--json] [--flat]` (issue #198) — the tree-grouped
// session listing, intercepted like trajectory: no agent boot.
// `fa session repair <sessionId|path> [--dry-run]` (gh-1073) — ledger
// surgery on a bloated session file, also without booting the agent.
final sessionList = parsed.sessionList;
if (sessionList != null) {
  final io = _TerminalCliIO(headless: true);
  final listEnv = LocalExecutionEnv(
    cwd: parsed.cwd ?? Directory.current.path,
  );
  final sessionRoot = parsed.sessionRoot ?? _defaultSessionRoot();
  if (sessionList.verb == 'repair') {
    exit(
      await runSessionRepairCliCommand(
        write: io.write,
        writeln: io.writeln,
        env: listEnv,
        sessionRoot: sessionRoot,
        sessionId: sessionList.repairTarget,
        dryRun: sessionList.dryRun,
        presenceStore: FileSessionPresenceStore(
          env: listEnv,
          root: sessionRoot,
        ),
      ),
    );
  }
  exit(
    await runSessionListCliCommand(
      write: io.write,
      writeln: io.writeln,
      env: listEnv,
      sessionRoot: sessionRoot,
      cwd: listEnv.cwd,
      json: sessionList.json,
      flat: sessionList.flat,
    ),
  );
}

// JS extension bootstrap (.fa/bootstrap.yaml, project then user): every
// normal start applies it idempotently before the REPL or headless run;
// E15 soft-fail lines go to stderr. FA_EXT_BOOTSTRAP_STRICT=1 makes a
// bootstrap failure fatal instead.
try {
  await applyBootstrapIfPresent(
    io: _TerminalCliIO(headless: parsed.isHeadless),
    env: LocalExecutionEnv(cwd: parsed.cwd ?? Directory.current.path),
    projectDir: parsed.cwd ?? Directory.current.path,
    userDir: _homeDir(),
    strict: _envTruthy('FA_EXT_BOOTSTRAP_STRICT'),
  );
} on Object catch (error) {
  _fail('ext bootstrap failed: $error');
}

// Headless prompt resolution: --prompt-file read as UTF-8 verbatim
// (missing/unreadable = usage error); -p verbatim; a first positional
// naming an existing file inlines text files (.md/.markdown/.txt) or
// attaches other files as a path reference; anything else is plain
// prompt text.
final String? headlessPrompt;
try {
  headlessPrompt = resolveHeadlessPrompt(
    prompt: parsed.prompt,
    promptFile: parsed.promptFile,
    positionals: parsed.positionals,
  );
} on CliArgsException catch (error) {
  _fail(error.message);
}

// `fa config check|path|get|set` runs BEFORE loadCliConfig: check must
// be able to diagnose exactly the broken config that would abort boot
// (issue #29). homeDir may be null — the service reports the global
// scope honestly.
final earlyConfigCmd = parsed.config;
if (earlyConfigCmd != null && earlyConfigCmd.verb != 'export-providers') {
  exit(
    await runConfigServiceCommand(
      earlyConfigCmd,
      io: _TerminalCliIO(headless: true),
      env: LocalExecutionEnv(cwd: Directory.current.path),
      homeDir: homeDirectory(),
    ),
  );
}

final home = homeDirectory();
if (home == null || home.isEmpty) {
  _fail('cannot resolve home directory; pass --session-root');
}
late final CliConfig saved;
try {
  saved = loadCliConfig(home);
} on ConfigException catch (error) {
  _fail('invalid ~/.fah/config.yaml: ${error.message}');
}
// Provider watchdog overrides (`providerTimeouts:` section): process-wide,
// read by the adapters' connect/idle watchdogs on every request. The
// FA_PROVIDER_TIMEOUT_SECONDS env value folds in over the section
// (issue #1036: non-streaming fetch bound; env wins for CI runners).
try {
  providerTimeoutsOverride = applyProviderTimeoutEnvOverride(
    saved.providerTimeouts,
    Platform.environment['FA_PROVIDER_TIMEOUT_SECONDS'],
  );
} on ConfigException catch (error) {
  _fail(error.message);
}

// Auto-update boot hook (issue #1377, `auto_update:` config): `off` is
// zero network; `notify` runs one bounded check and prints a
// once-per-process banner; `on` applies + restarts into the successor
// BEFORE the session boots — applied → exit(0), the successor inherits
// stdio + this argv and resumes the session through its own --session
// flag. Help/version and the update/uninstall quick commands exited
// above; serve/wire-daemon runs are skipped (a daemon must not restart
// itself under connected clients), and `fa config export-providers`
// (intercepted below) is not a session boot either.
final autoUpdateNotify = AutoUpdateNotify();
switch (bootUpdateAction(
  mode: saved.autoUpdate,
  serveOrDaemon:
      serve.serveA2a ||
      serve.serveBridge ||
      wireServe.wireServe ||
      parsed.config != null,
)) {
  case BootUpdateAction.none:
    break;
  case BootUpdateAction.notifyCheck:
    // Background probe: the boot never waits on it — the banner prints
    // WHEN the answer lands (a dead endpoint just stays silent; the
    // 3 s bound keeps a hung socket from printing late into a live
    // TUI). stderr — the same pre-TUI boot-notice channel as the
    // config warnings above.
    unawaited(() async {
      // The probe OWNS its client: `.timeout` abandons the in-flight
      // request at the bound, and closing here (finally, always) is
      // what actually releases the socket — not the inner finally,
      // which only runs when the abandoned fetch itself settles.
      final probe = http.Client();
      try {
        final latest = await fetchLatestTag(client: probe).timeout(
          const Duration(seconds: 3),
          onTimeout: () => null,
        );
        if (latest != null &&
            compareVersions(latest, packageVersion) > 0) {
          final banner = autoUpdateNotify.banner(latest);
          if (banner != null) stderr.writeln(banner);
        }
      } finally {
        probe.close();
      }
    }());
  case BootUpdateAction.applyAndExit:
    final outcome = await applyUpdate(
      currentVersion: packageVersion,
      launchArgs: args,
    );
    switch (outcome) {
      case ApplyUpdateOutcome.applied:
        exit(0);
      case ApplyUpdateOutcome.upToDate:
        break;
      case ApplyUpdateOutcome.refusedDevRun:
        stderr.writeln('fa: auto update unavailable for source runs');
      case ApplyUpdateOutcome.unsupportedPlatform:
        break; // The engine swapped and printed the restart hint.
      case ApplyUpdateOutcome.convergenceGuard:
        stderr.writeln(
          'fa: auto update paused — the same release was already '
          'attempted and is still not resolving; continuing on '
          'v$packageVersion',
        );
      case _:
        // Never crash the boot: one warn, then continue on the current
        // binary (restartFailed keeps the already-swapped new binary).
        stderr.writeln(
          'fa: auto update failed (${outcome.name}) — '
          'continuing on v$packageVersion',
        );
    }
}

// Session image registry (`images:` section, issue #171): process-wide,
// read inside the agent loop's request build. Default: on.
imageRegistryConfig = saved.images ?? const ImageRegistryConfig();

