          302,
          headers: {
            'location':
                'https://github.com/IstiN/flutter_agent_harness/'
                'releases/tag/v0.1.0',
          },
        );
      });
      final outcome = await applyUpdate(
        currentVersion: '0.1.0',
        launchArgs: const [],
        statePath: '${temp.path}/update-state.json',
