import 'dart:typed_data';
import 'package:cryptography/cryptography.dart';
import 'package:crypto/crypto.dart' as crypto;

bool listEquals(List<int> a, List<int> b) {
  if (a.length != b.length) return false;
  for (var i = 0; i < a.length; i++) {
    if (a[i] != b[i]) return false;
  }
  return true;
}

final class DerReader {
  DerReader(this.bytes);
  final Uint8List bytes;
  var pos = 0;
  Uint8List take(int tag) {
    if (pos >= bytes.length || bytes[pos++] != tag) {
      throw const FormatException('unexpected DER tag');
    }
    var length = bytes[pos++];
    if (length & 0x80 != 0) {
      final count = length & 0x7f;
      length = 0;
      for (var i = 0; i < count; i++) {
        length = (length << 8) | bytes[pos++];
      }
    }
    final value = bytes.sublist(pos, pos + length);
    pos += length;
    return value;
  }
}

const rsaOid = [0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 0x01, 0x01, 0x01];
Uint8List unsigned(List<int> b) =>
    b.length > 1 && b.first == 0 ? Uint8List.fromList(b.sublist(1)) : Uint8List.fromList(b);

RsaPublicKey parsePem(String pem) {
  final b64 = pem.split('\n').where((l) => !l.startsWith('-----')).join();
  final der = base64Decode(b64.replaceAll(RegExp(r'\s'), ''));
  final spki = DerReader(der);
  final content = DerReader(spki.take(0x30));
  final alg = DerReader(content.take(0x30));
  if (!listEquals(alg.take(0x06), rsaOid)) {
    throw const FormatException('not rsaEncryption');
  }
  final rsa = DerReader(DerReader(content.take(0x03).sublist(1)).take(0x30));
  return RsaPublicKey(n: unsigned(rsa.take(0x02)), e: unsigned(rsa.take(0x02)));
}

