final class DerReader {
  DerReader(this.bytes);
  final Uint8List bytes;
  var pos = 0;
  Uint8List take(int tag) {
    if (pos >= bytes.length || bytes[pos++] != tag) {
      throw const FormatException('unexpected DER tag');
